fn fabric_spine_module_tree_exists() {
    let r = root();
    assert!(
        r.join("src/fabric_spine/mod.rs").is_file(),
        "src/fabric_spine/mod.rs required for architecture B"
    );
    assert!(
        r.join("src/fabric_spine/change_detection.rs").is_file(),
        "change-detection must live under fabric_spine"
    );
    assert!(
        r.join("src/fabric_spine/session_lock.rs").is_file(),
        "session-lock gates the fabric (not a session hub)"
    );
}

