fn lexicon_module_owns_traits() {
    let r = root();
    assert!(r.join("src/lexicon/mod.rs").is_file());
    assert!(
        r.join("src/lexicon/traits.rs").is_file(),
        "verify-traits logic belongs in lexicon"
