#[test]
fn change_detection_reports_clean_after_init() {
    let dir = TempDir::new().unwrap();
    let out = run(&dir, &["init"]);
    assert!(out.status.success(), "init failed: {}", String::from_utf8_lossy(&out.stderr));
    let out = run(&dir, &["verify", "all"]);
    assert!(
        out.status.success(),
