        String::from_utf8_lossy(&out.stderr)
    );
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        !stdout.to_lowercase().contains("drift"),
        "fresh init should not report drift, got: {}",
        stdout
    );
}

#[test]
fn change_detection_warns_on_external_drift() {
    let dir = TempDir::new().unwrap();
    assert!(run(&dir, &["init"]).status.success());
    // Snapshot baseline via a fabric-owned mutation
    assert!(
        run(
            &dir,
            &[
                "add",
                "term",
                "--term",
                "residue",
                "--definition",
                "what remains",
            ],
        )
        .status
        .success()
    );

    // External edit bypassing CLI (drift)
    let terms = dir.path().join("residual/terminology.csv");
    let mut contents = fs::read_to_string(&terms).unwrap();
    contents.push_str("smuggled,external edit,core,\n");
    fs::write(&terms, contents).unwrap();

    let out = run(&dir, &["verify", "all"]);
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    let combined = format!("{}{}", stdout, stderr).to_lowercase();
    assert!(
        combined.contains("drift") || combined.contains("change"),
        "expected drift/change warning after external edit, got stdout={} stderr={}",
        stdout,
        stderr
    );
}

#[test]
fn session_lock_serializes_fabric_mutations() {
    // Unit-level proof is in fabric_spine::session_lock tests; this checks the
    // lock file appears during a mutation path after init.
    let dir = TempDir::new().unwrap();
    assert!(run(&dir, &["init"]).status.success());
    let lock = dir.path().join("residual/.session.lock");
    // Lock should not linger after successful add
    assert!(
        run(
            &dir,
            &[
                "add",
                "attractor",
                "--name",
                "Stability",
                "--valence",
                "positive",
                "--description",
                "stable",
            ],
        )
        .status
        .success()
    );
    assert!(
        !lock.exists(),
        "session lock must be released after successful fabric mutation"
    );
}

//! Session lock — gates fabric mutations (not a session hub).
use anyhow::{bail, Context, Result};
use std::fs;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const LOCK_NAME: &str = ".session.lock";
const DEFAULT_TTL_SECS: u64 = 30;

pub struct SessionLock {
    path: PathBuf,
}

impl SessionLock {
    pub fn path(residual_dir: &Path) -> PathBuf {
        residual_dir.join(LOCK_NAME)
    }

    /// Acquire an exclusive fabric gate. Stale locks past TTL are stolen.
    pub fn acquire(residual_dir: &Path) -> Result<Self> {
        fs::create_dir_all(residual_dir)?;
        let path = Self::path(residual_dir);
        if path.exists() {
            if is_stale(&path, DEFAULT_TTL_SECS)? {
                let _ = fs::remove_file(&path);
            } else {
                bail!(
                    "fabric session lock held at {} — another mutation in progress",
                    path.display()
                );
            }
        }
        let pid = std::process::id();
        let now = now_secs();
        fs::write(&path, format!("pid={}\nacquired={}\n", pid, now))
            .with_context(|| format!("write lock {}", path.display()))?;
        Ok(Self { path })
    }

    pub fn release(self) -> Result<()> {
        if self.path.exists() {
            fs::remove_file(&self.path)
                .with_context(|| format!("release lock {}", self.path.display()))?;
        }
        Ok(())
    }
}

impl Drop for SessionLock {
    fn drop(&mut self) {
        if self.path.exists() {
            let _ = fs::remove_file(&self.path);
        }
    }
}

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0))
        .as_secs()
}

fn is_stale(path: &Path, ttl_secs: u64) -> Result<bool> {
    let contents = fs::read_to_string(path)?;
    let acquired = contents
        .lines()
        .find_map(|l| l.strip_prefix("acquired=").and_then(|v| v.parse::<u64>().ok()))
        .unwrap_or(0);
    Ok(now_secs().saturating_sub(acquired) > ttl_secs)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn acquire_and_release_clears_lockfile() {
        let dir = tempdir().unwrap();
        let lock = SessionLock::acquire(dir.path()).unwrap();
        assert!(SessionLock::path(dir.path()).exists());
        lock.release().unwrap();
        assert!(!SessionLock::path(dir.path()).exists());
    }

    #[test]
    fn second_acquire_fails_while_held() {
        let dir = tempdir().unwrap();
        let _held = SessionLock::acquire(dir.path()).unwrap();
        let err = SessionLock::acquire(dir.path()).unwrap_err();
        assert!(
            err.to_string().contains("lock"),
            "expected lock error, got {}",
            err
        );
    }
}

//! Change-detection — content hashes of managed residual files.
//! Fabric owns the snapshot; external edits surface as drift on verify.
use anyhow::{Context, Result};
use std::collections::BTreeMap;
use std::fs;
use std::hash::{Hash, Hasher};
use std::path::{Path, PathBuf};

const SNAPSHOT_NAME: &str = ".fabric-hashes";

/// Managed residual paths (relative to residual_dir) that the fabric snapshots.
pub fn managed_rel_paths(residual_dir: &Path) -> Result<Vec<String>> {
    let mut paths = vec![
        "stressors.csv".to_string(),
        "purposes.csv".to_string(),
        "attractors.csv".to_string(),
        "terminology.csv".to_string(),
        "config.toml".to_string(),
    ];

    for sub in &["personas", "iterations", "research"] {
        let dir = residual_dir.join(sub);
        if !dir.is_dir() {
            continue;
        }
        let mut entries: Vec<_> = fs::read_dir(&dir)?
            .filter_map(|e| e.ok())
            .filter(|e| e.path().is_file())
            .collect();
        entries.sort_by_key(|e| e.file_name());
        for e in entries {
            let name = e.file_name().to_string_lossy().into_owned();
            paths.push(format!("{}/{}", sub, name));
        }
    }
    paths.sort();
    Ok(paths)
}

pub fn snapshot_path(residual_dir: &Path) -> PathBuf {
    residual_dir.join(SNAPSHOT_NAME)
}

fn hash_bytes(data: &[u8]) -> u64 {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    data.hash(&mut hasher);
    hasher.finish()
}

pub fn current_hashes(residual_dir: &Path) -> Result<BTreeMap<String, String>> {
    let mut map = BTreeMap::new();
    for rel in managed_rel_paths(residual_dir)? {
        let path = residual_dir.join(&rel);
        let digest = if path.exists() {
            let bytes = fs::read(&path).with_context(|| format!("read {}", path.display()))?;
            format!("{:016x}", hash_bytes(&bytes))
        } else {
            "missing".to_string()
        };
        map.insert(rel, digest);
    }
    Ok(map)
}

pub fn write_snapshot(residual_dir: &Path) -> Result<()> {
    let hashes = current_hashes(residual_dir)?;
    let mut body = String::from("# fabric-spine change-detection snapshot\n");
    for (path, digest) in &hashes {
        body.push_str(&format!("{}={}\n", path, digest));
    }
    fs::write(snapshot_path(residual_dir), body)
        .with_context(|| format!("write {}", snapshot_path(residual_dir).display()))?;
    Ok(())
}

pub fn load_snapshot(residual_dir: &Path) -> Result<Option<BTreeMap<String, String>>> {
    let path = snapshot_path(residual_dir);
    if !path.exists() {
        return Ok(None);
    }
    let text = fs::read_to_string(&path)?;
    let mut map = BTreeMap::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some((k, v)) = line.split_once('=') {
            map.insert(k.to_string(), v.to_string());
        }
    }
    Ok(Some(map))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DriftReport {
    pub drifted: Vec<String>,
    pub added: Vec<String>,
    pub removed: Vec<String>,
}

impl DriftReport {
    pub fn is_clean(&self) -> bool {
        self.drifted.is_empty() && self.added.is_empty() && self.removed.is_empty()
    }
}

pub fn detect_drift(residual_dir: &Path) -> Result<DriftReport> {
    let Some(baseline) = load_snapshot(residual_dir)? else {
        // No snapshot yet — treat as clean; caller may seed one.
        return Ok(DriftReport {
            drifted: vec![],
            added: vec![],
            removed: vec![],
        });
    };
    let current = current_hashes(residual_dir)?;
    let mut drifted = Vec::new();
    let mut added = Vec::new();
    let mut removed = Vec::new();

    for (path, digest) in &current {
        match baseline.get(path) {
            Some(prev) if prev != digest => drifted.push(path.clone()),
            Some(_) => {}
            None => added.push(path.clone()),
        }
    }
    for path in baseline.keys() {
        if !current.contains_key(path) {
            removed.push(path.clone());
        }
    }
    Ok(DriftReport {
        drifted,
        added,
        removed,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn snapshot_then_external_edit_reports_drift() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        fs::create_dir_all(&residual).unwrap();
        fs::write(residual.join("terminology.csv"), "term,definition,domain,related_terms\n").unwrap();
        fs::write(residual.join("stressors.csv"), "id,description,naive_change,traits,components_affected,attractor_id\n").unwrap();
        fs::write(residual.join("purposes.csv"), "id,description,feature,traits,components_enabled,attractor_id\n").unwrap();
        fs::write(residual.join("attractors.csv"), "id,name,valence,description,phase_state\n").unwrap();
        fs::write(residual.join("config.toml"), "#\n").unwrap();
        write_snapshot(&residual).unwrap();
        assert!(detect_drift(&residual).unwrap().is_clean());

        let mut terms = fs::read_to_string(residual.join("terminology.csv")).unwrap();
        terms.push_str("smuggled,x,core,\n");
        fs::write(residual.join("terminology.csv"), terms).unwrap();

        let report = detect_drift(&residual).unwrap();
        assert!(!report.is_clean());
        assert!(report.drifted.iter().any(|p| p == "terminology.csv"));
    }
}

//! Fabric-first spine (architecture B): storage I/O, append, init,
//! change-detection, and verify-all orchestration.
//!
//! skill-data / skill-interface remain clients. session-lock gates this fabric.
use anyhow::Result;
use crate::cli::{AddTarget, ListTarget, VerifyCheck};
use crate::config::Config;

pub mod change_detection;
pub mod session_lock;

use change_detection::{detect_drift, write_snapshot};
use session_lock::SessionLock;

/// storage-init — owned by the fabric.
pub fn init(cfg: &Config) -> Result<()> {
    let _lock = SessionLock::acquire(&cfg.residual_dir)?;
    crate::storage::init_dirs_and_files(cfg)?;
    write_snapshot(&cfg.residual_dir)?;
    println!("Initialized residual/ at {}", cfg.residual_dir.display());
    Ok(())
}

/// storage-append / storage-io mutation path — gated by session-lock.
pub fn add(cfg: &Config, target: AddTarget) -> Result<()> {
    let _lock = SessionLock::acquire(&cfg.residual_dir)?;
    crate::storage::add_entry(cfg, target)?;
    write_snapshot(&cfg.residual_dir)?;
    Ok(())
}

/// Read-side list (no lock required for prototype).
pub fn list(cfg: &Config, target: ListTarget) -> Result<()> {
    crate::storage::list_entries(cfg, target)
}

/// verify-all orchestration — traits (lexicon) + links + change-detection.
pub fn verify(cfg: &Config, check: VerifyCheck) -> Result<()> {
    match check {
        VerifyCheck::Traits => {
            let violations = crate::lexicon::check_traits(cfg)?;
            if violations.is_empty() {
                println!("OK: all traits reference at least one terminology term.");
            } else {
                for v in &violations {
                    println!(
                        "VIOLATION [{}] {}: {} — {}",
                        v.source, v.id, v.trait_str, v.reason
                    );
                }
                println!("{} trait violation(s) found.", violations.len());
            }
        }
        VerifyCheck::Links => {
            let violations = crate::verify::check_links(cfg)?;
            if violations.is_empty() {
                println!("OK: all attractor links are valid.");
            } else {
                for v in &violations {
                    println!(
                        "VIOLATION [{}] {}: missing attractor '{}'",
                        v.source, v.id, v.missing_attractor_id
                    );
                }
                println!("{} link violation(s) found.", violations.len());
            }
        }
        VerifyCheck::All => {
            let trait_violations = crate::lexicon::check_traits(cfg)?;
            let link_violations = crate::verify::check_links(cfg)?;
            let drift = detect_drift(&cfg.residual_dir)?;

            for v in &trait_violations {
                println!(
                    "TRAIT VIOLATION [{}] {}: {} — {}",
                    v.source, v.id, v.trait_str, v.reason
                );
            }
            for v in &link_violations {
                println!(
                    "LINK VIOLATION [{}] {}: missing attractor '{}'",
                    v.source, v.id, v.missing_attractor_id
                );
            }

            if !drift.is_clean() {
                println!("DRIFT: residual files changed outside the fabric:");
                for p in &drift.drifted {
                    println!("  changed: {}", p);
                }
                for p in &drift.added {
                    println!("  added: {}", p);
                }
                for p in &drift.removed {
                    println!("  removed: {}", p);
                }
            }

            let total = trait_violations.len() + link_violations.len();
            if total == 0 && drift.is_clean() {
                println!("OK: all checks passed.");
            } else if total == 0 {
                println!("OK: trait/link checks passed; change-detection reported drift.");
            } else {
                println!("{} total violation(s) found.", total);
            }
        }
    }
    Ok(())
}

use anyhow::Result;
use std::fs;
use crate::config::Config;
use crate::cli::{AddTarget, ListTarget};

pub mod attractors;
pub mod iterations;
pub mod personas;
pub mod purposes;
pub mod research;
pub mod stressors;
pub mod terminology;

/// Low-level residual directory + CSV bootstrap (owned entry point: fabric_spine::init).
pub fn init_dirs_and_files(cfg: &Config) -> Result<()> {
    let dir = &cfg.residual_dir;
    fs::create_dir_all(dir.join("iterations"))?;
    fs::create_dir_all(dir.join("personas"))?;
    fs::create_dir_all(dir.join("research"))?;

    let config_path = dir.join("config.toml");
    if !config_path.exists() {
        fs::write(
            &config_path,
            "# residual configuration\n[validation]\nstrict = true\n\n[skills]\ntoken_warn = 1000\n",
        )?;
    }

    let csvs: &[(&str, &str)] = &[
        (
            "stressors.csv",
            "id,description,naive_change,traits,components_affected,attractor_id",
        ),
        (
            "purposes.csv",
            "id,description,feature,traits,components_enabled,attractor_id",
        ),
        (
            "attractors.csv",
            "id,name,valence,description,phase_state",
        ),
        (
            "terminology.csv",
            "term,definition,domain,related_terms",
        ),
    ];
    for (filename, header) in csvs {
        let path = dir.join(filename);
        if !path.exists() {
            fs::write(&path, format!("{}\n", header))?;
        }
    }
    Ok(())
}

/// Append/create entry (owned entry point: fabric_spine::add).
pub fn add_entry(cfg: &Config, target: AddTarget) -> Result<()> {
    let dir = &cfg.residual_dir;
    match target {
        AddTarget::Stressor {
            description,
            attractor_id,
            naive_change,
            traits,
            components,
        } => {
            let existing = stressors::load(dir)?;
            let id = stressors::next_id(&existing);
            stressors::append(
                dir,
                stressors::Stressor {
                    id: id.clone(),
                    description,
                    attractor_id,
                    naive_change,
                    traits,
                    components_affected: components,
                },
            )?;
            println!("Added stressor {}", id);
        }
        AddTarget::Purpose {
            description,
            attractor_id,
            feature,
            traits,
            components,
        } => {
            let existing = purposes::load(dir)?;
            let id = purposes::next_id(&existing);
            purposes::append(
                dir,
                purposes::Purpose {
                    id: id.clone(),
                    description,
                    attractor_id,
                    feature,
                    traits,
                    components_enabled: components,
