pub fn install(name: &str, agent: &str, global: bool) -> Result<()> {
    let (content, _version) = find(name).with_context(|| format!("skill '{}' not found", name))?;
    let agent_parsed: install_mod::Agent = agent.parse()?;
    let path = install_mod::install_path(name, &agent_parsed, global)?;
    install_mod::write_skill(&path, content)?;
    println!("Installed '{}' to {}", name, path.display());
    Ok(())
}

pub fn check(name: &str, agent: &str) -> Result<()> {
    let (_content, embedded_version) =
        find(name).with_context(|| format!("skill '{}' not found", name))?;
    let agent_parsed: install_mod::Agent = agent.parse()?;
    match install_mod::installed_version(name, &agent_parsed, false)? {
        None => {
            println!("'{}' is not installed for agent '{}'.", name, agent);
        }
        Some(installed_ver) => {
            if installed_ver == embedded_version {
                println!("'{}' is up to date (version {}).", name, installed_ver);
            } else {
                println!(
                    "'{}' is outdated: installed version {}, embedded version {}.",
                    name, installed_ver, embedded_version
                );
            }
        }
    }
    Ok(())
}

